_choice_shortcut_name() {
    shortcuts list 2>/dev/null
}

_choice_shortcut_name_or_identifier() {
    local line name uuid
    while IFS= read -r line; do
        [[ -n "$line" ]] || continue
        if [[ "$line" =~ ^(.+)\ \(([^()]+)\)$ ]]; then
            name="${BASH_REMATCH[1]}"
            uuid="${BASH_REMATCH[2]}"
            printf '%s\n' "$name"
            printf '%s\0\n' "$uuid"
        else
            printf '%s\n' "$line"
        fi
    done < <(shortcuts list --show-identifiers 2>/dev/null)
}
